import { useState, useEffect } from 'react'
import { ForgotPinContainerStyle } from './index.style'
import { CustomText, Container, Button } from '../../../../components'
import { PIN_NEW, SMARTPHONE } from '../../../../images'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import NumericInput from '../../../../components/NumericInput'
import { ERROR_LANG } from '../../../../lang'
import { useHistory } from 'react-router'
import SendOtpModalContainer from '../../../../components/SendOtpModalPin/container'
import AuthActions from '../../../../redux/auth/action'
import ErrorActions from '../../../../redux/error/action'
import { connect } from 'react-redux'
import OtpInput from '../../../../components/PinOtpInput'
import PinInput from '../../../../components/PinInput'
import ShowSnackbar from '../../../../components/ShowNotification'
const { resetErrorRedux } = ErrorActions
const { verifyOtp, updatePin, sendOtp, resetAuthStore } = AuthActions

function ForgotPinContainer (props, { location }) {
  const history = useHistory()
  const { verifyOtp, updatePin, sendOtp, resetAuthStore, resetErrorRedux } = props
  const [error, setError] = useState(false)
  const [phone, setPhone] = useState('')
  const [pin, setPin] = useState('')
  const [step, setStep] = useState(0)
  const [title, setTitle] = useState('Masukkan Nomor Ponsel')
  const [otp, setOtp] = useState('')
  const [operationId, setOperationId] = useState('')
  const [otpMedium, setOtpMedium] = useState('sms')
  const crypto = require('crypto')

  useEffect(() => {
    if (step === 1) {
      setTitle('Kirim OTP Via')
    }
    if (step === 2) {
      setTitle('Kode OTP')
    }
    if (step === 3) {
      setTitle('Buat PIN Baru')
    }
    if (step === 4) {
      setTitle('Konfirmasi PIN')
    }
  }, [step])

  useEffect(() => {
    if (props.sendOtpStatus.result === 'Success') {
      setOperationId(props.sendOtpStatus.operation_id)
      resetAuthStore(['sendOtpStatus'])
    } else {
      resetAuthStore(['sendOtpStatus'])
    }
  }, [props.sendOtpStatus, operationId, resetAuthStore])

  useEffect(() => {
    if (step === 1 && props.sendOtpStatus.result === 'Success') {
      setStep(2)
    } else if (step === 1 && props.sendOtpError) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: 'Tunggu 30 menit, untuk mengganti nomor'
        })
      }
      resetErrorRedux(['SEND_OTP'])
    }
  }, [props.sendOtpStatus, props.sendOtpError, step, resetAuthStore, resetErrorRedux])

  useEffect(() => {
    if (otp && props.verifyOtpStatus === 'OTP successfully verified') {
      setStep(3)
      resetAuthStore(['verifyOtpStatus'])
    } else if (props.verifyOtpError) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: 'Invalid OTP code, please try again'
        })
      }
      resetErrorRedux(['VERIFY_OTP'])
    }
  }, [props.verifyOtpStatus, props.verifyOtpError, otp, resetAuthStore, resetErrorRedux])

  useEffect(() => {
    if (otp && props.updatePinStatus === 'Pin successfully updated') {
      history.push('/new-pin-success')
      resetAuthStore(['updatePinStatus'])
    } else if (props.updatePinError) {
      if (ShowSnackbar.error) {
        ShowSnackbar.error({
          visible: true,
          text: 'Error'
        })
      }
    }
  }, [props.updatePinError, props.updatePinStatus, otp, history, resetAuthStore])

  const handlePhoneNumber = (value) => {
    setPhone(value)
    setError(false)
  }

  const hashString = (input) => {
    return crypto.createHash('sha256').update(input).digest('hex')
  }

  const handleSubmit = () => {
    if (phone === '') {
      setError(true)
      return
    }
    setStep(1)
  }

  const handleSave = () => {
    const body = {
      channel: otpMedium,
      phone_no: phone
    }
    sendOtp(body)
  }

  const submitOtp = (value) => {
    const body = {
      otp: value,
      operation_id: operationId
    }
    verifyOtp(body)
    setOtp(value)
  }

  const handleSubmitPin = (value) => {
    if (value === pin) {
      const body = {
        phone_no: phone,
        new_pin: (hashString(value)),
        otp: otp,
        operation_id: operationId
      }
      updatePin(body)
    } else {
      setError(true)
    }
  }

  const handlePin = (value) => {
    setPin(value)
    setStep(4)
  }

  const handleBackButton = () => {
    if (step === 0) {
      history.push('/login')
    }
    if (step === 1) {
      setStep(0)
    }
    if (step === 2) {
      setStep(0)
    }
    if (step === 3) {
      setStep(0)
    }
    if (step === 4) {
      setStep(3)
    }
  }

  return (
    <Container
      title={title}
      showInnerHeader
      displayBackButton
      onBackClick={handleBackButton}
    >
      <ForgotPinContainerStyle>
        {(step === 3 || step === 4) &&
          <div className='text-container'>
            <div>
              <img src={PIN_NEW} alt='' />
            </div>
            <CustomText fontColor='#333333' size='14px' weight={700} textAlign='center' top='20px' bottom='10px'>
              {step === 3 ? 'Buat PIN Baru' : 'Konfirmasi PIN'}
            </CustomText>
            <CustomText fontColor='#333333' size='12px' weight={500} textAlign='center' bottom='8%'>
              {step === 3 ? 'Masukkan 4 digit angka untuk membuat PIN baru. PIN akan digunakan untuk otentikasi masuk aplikasi, proses pembayaran dan konfirmasi lainnya.' : 'Masukkan kembali 4 digit PIN untuk konformasi.'}
            </CustomText>
          </div>}
        {step === 0 &&
          <>
            <div className='text-container'>
              <img
                src={SMARTPHONE}
                alt='phone'
                className='phone-icon'
              />
              <CustomText
                size='14px'
                color={AgentColorPallette.black}
                weight='700'
                className=''
                textAlign='center'
                top='20px'
                bottom='10px'
              >
                Masukkan Nomor Ponsel
              </CustomText>
              <CustomText
                size='12px'
                color={AgentColorPallette.black}
                weight='500'
                className=''
                textAlign='center'
                bottom='20px'
              >
                Silakan masukkan nomor ponsel Anda yang terdaftar di aplikasi Mitra App.
              </CustomText>
            </div>
            <NumericInput
              errorField={error && ERROR_LANG.requiredField}
              placeholder='No Ponsel (08xxxxxxxx)'
              name='phone_no'
              type='phone_number'
              className='login-mobile'
              showError={error && ERROR_LANG.requiredField}
              errorCenter
              autoFocus
              onChange={handlePhoneNumber}
            />
            <Button onClick={handleSubmit} className='submit-otp-button' textColor='#000000'>
              Kirim OTP
            </Button>
          </>}
        {step === 1 && <SendOtpModalContainer padding='0px' handleSave={handleSave} otpMedium={otpMedium} setOtpMedium={setOtpMedium} />}
        {step === 2 &&
          <div className='text-container'>
            <div>
              <img src={SMARTPHONE} alt='' />
            </div>
            <CustomText fontColor='#333333' color={AgentColorPallette.black} size='14px' weight={700} textAlign='center' top='4%' bottom='3%'>Kode OTP</CustomText>
            <CustomText fontColor='#333333' color={AgentColorPallette.black} size='12px' weight={500} textAlign='center' bottom=''>
              Masukkan OTP yang terkirim ke nomor ponsel
            </CustomText>
            <CustomText fontColor='#333333' size='12px' weight={700} textAlign='center' bottom='8%'>
              {phone}
            </CustomText>
            <OtpInput
              onComplete={submitOtp}
            />
            <CustomText fontColor='#333333' color={AgentColorPallette.black} size='12px' weight={500} textAlign='center' top='10px'>
              OTP berakhir dalam 12s.
            </CustomText>
          </div>}
        {
          step === 3 &&
            <PinInput onComplete={handlePin} />
        }
        {
          step === 4 &&
            <>
              <PinInput
                onComplete={handleSubmitPin}
                error={error}
                setError={setError}
              />
              {
                error &&
                  <CustomText size={12} weight={500} textAlign='center' top='20px' bottom='' color='#DC0000'>
                PIN tidak sama dengan yang sebelumnya.
                  </CustomText>
              }
            </>
        }
      </ForgotPinContainerStyle>
    </Container>
  )
}

export default connect((state) => ({
  sendOtpLoading: state.Loading.SEND_OTP,
  sendOtpError: state.Error.SEND_OTP,
  sendOtpStatus: state.Auth.sendOtpStatus,

  verifyOtpLoading: state.Loading.VERIFY_OTP,
  verifyOtpError: state.Error.VERIFY_OTP,
  verifyOtpStatus: state.Auth.verifyOtpStatus,

  updatePinLoading: state.Loading.UPDATE_PIN,
  updatePinError: state.Error.UPDATE_PIN,
  updatePinStatus: state.Auth.updatePinStatus
}), {
  updatePin,
  verifyOtp,
  sendOtp,
  resetAuthStore,
  resetErrorRedux
})(ForgotPinContainer)
